<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\Shop\CategoryTemplate;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use Illuminate\Validation\ValidationException;class DeleteController extends BaseController{    /**     * @param Request $request     * @return array     * @throws ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        try {           $res = (new CategoryTemplate())->categoryDelete($input);            // 日志记录            $this->writeOperatorLog('删除【' . $input['id'] . '】分类');        } catch (Error $error) {            Log::info('删除分类失败', $error->data);            notice(100000, [$error->getMessage()]);        } catch (\Exception $e) {            Log::info('删除分类失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($res);    }    /**     * 验证数据     * @param $request     * @return array     * @throws ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'id'          => [                'required',                'integer'            ],            'pid'         => 'required|integer',            'cate_tpl_id' => 'required|integer',        ];        $messages = [            'id.*'          => '分类不存在',            'pid.*'         => '父级ID不存在',            'cate_tpl_id.*' => '分类模版不存在',        ];        return $this->validate($request, $rule, $messages);    }}